"""Helpers for aggregating and querying well readings."""

from datetime import date
from typing import List, Optional

from models import Reading, Well, is_recovered


def latest_reading(readings: List[Reading]) -> Optional[Reading]:
    """Return the most recent reading in the list, or None if there are no readings."""
    if not readings:
        return None
    return max(readings, key=lambda r: r.reading_date)


def year_to_date_extraction(readings: List[Reading], as_of: date) -> float:
    """Sum extraction volumes for readings recorded within the current calendar year."""
    return sum(r.extraction_volume_m3 for r in readings if r.reading_date.year == as_of.year)


def recovery_status(well: Well, readings: List[Reading]) -> bool:
    """Check whether the well's water level has returned close to its baseline after pumping."""
    latest = latest_reading(readings)
    if latest is None:
        return False
    return is_recovered(well, latest.depth_to_water_m)
